  private body: number[][] = [[0, 0]];
  private fi = 0;
  private score = 0;
  private over = false;
  constructor(private width: number, private height: number, private food: number[][]) {}

  move(direction: string): number {
    if (this.over) return -1;
    const [hr, hc] = this.body[this.body.length - 1];
    const r = hr + (direction === "D" ? 1 : direction === "U" ? -1 : 0);
    const c = hc + (direction === "R" ? 1 : direction === "L" ? -1 : 0);
    if (r < 0 || r >= this.height || c < 0 || c >= this.width) { this.over = true; return -1; }
    const f = this.food[this.fi];
    if (f && f[0] === r && f[1] === c) { this.fi++; this.score++; }
    else this.body.shift();
    if (this.body.some(([a, b]) => a === r && b === c)) { this.over = true; return -1; }
    this.body.push([r, c]);
    return this.score;
  }
