class SnakeGame {
  private q: number[] = [0]; // cells as row * width + col, tail first
  private head = 0;          // index of the tail inside q
  private occupied = new Set<number>([0]);
  private fi = 0;
  private score = 0;
  private over = false;
  constructor(private width: number, private height: number, private food: number[][]) {}

  move(direction: string): number {
    if (this.over) return -1;
    const last = this.q[this.q.length - 1];
    let r = Math.floor(last / this.width), c = last % this.width;
    if (direction === "U") r--;
    else if (direction === "D") r++;
    else if (direction === "L") c--;
    else c++;
    if (r < 0 || r >= this.height || c < 0 || c >= this.width) { this.over = true; return -1; }
    const cell = r * this.width + c;
    const f = this.food[this.fi];
    if (f && f[0] === r && f[1] === c) { this.fi++; this.score++; }
    else this.occupied.delete(this.q[this.head++]);
    if (this.occupied.has(cell)) { this.over = true; return -1; }
    this.q.push(cell);
    this.occupied.add(cell);
    return this.score;
  }
}

